// HWA recorder - a console diagnostic for hwa_extension.js, independent of it.
// Generated by tools/build_recorder.js - edit the template, not tools/hwa_recorder.js.
//
// Paste the whole file into the DevTools console on the game tab. Until stopped it records:
//  - how often the game actually draws, against how often the browser offers a frame
//  - whether a pixel read right after the game's own frame ever comes back black
//  - which of the script's known screens match right now, as you move around the game
//  - every click on the canvas, yours and the macro's: coordinates and the colour under it
//  - unknown screens (popups and the like) as a coarse colour grid
//  - #gameLoader, canvas size and position, tab visibility, WebGL context loss, page errors, memory
// The log is kept in localStorage, so after a page reload paste the file again and it carries on.
// Controls: the panel in the bottom-left corner, or hwaRec.mark('text') / .dump() / .stop() / .clear()
(() => {
    'use strict'
    if (window.hwaRec) window.hwaRec.stop()

    const SCREENS = __SCREENS__

    const KEY = 'hwaRecLog'
    const MAX_LINES = 4000
    const STATS_EVERY_MS = 5000
    const SCREEN_EVERY_MS = 1000
    const BLACK_CHECK_EVERY = 10              // game frames between black checks - every read stalls the GPU
    const BLACK_CHECK_POINTS = [[0.5, 0.5], [0.25, 0.3], [0.75, 0.3], [0.25, 0.8], [0.75, 0.8]]
    const DEFAULT_THRESHOLD = 15
    const GRID_COLS = 6, GRID_ROWS = 4

    // ---------- log ----------
    let lines = []
    try { lines = JSON.parse(localStorage.getItem(KEY)) || [] } catch (e) {}
    const startedAt = Date.now()
    let persistTimer = null

    function stamp() {
        const d = new Date()
        return d.toLocaleTimeString('ru-RU', { hour12: false }) + '.' + String(d.getMilliseconds()).padStart(3, '0')
    }
    function add(kind, text) {
        lines.push(stamp() + ' [' + kind + '] ' + text)
        if (lines.length > MAX_LINES) lines.splice(0, lines.length - MAX_LINES)
        if (persistTimer == null) persistTimer = setTimeout(persist, 1000)
    }
    function persist() {
        persistTimer = null
        try { localStorage.setItem(KEY, JSON.stringify(lines)) } catch (e) {}
    }

    const cleanups = []
    function on(target, type, fn, opts) {
        target.addEventListener(type, fn, opts)
        cleanups.push(() => target.removeEventListener(type, fn, opts))
    }

    // ---------- page state ----------
    let canvas = document.getElementById('gameCanvas')
    if (!canvas) { console.log('HWA recorder: на странице нет #gameCanvas'); return }
    const loader = document.getElementById('gameLoader')
    const loaderState = () => loader ? getComputedStyle(loader).display : 'нет элемента'

    function geometry() {
        const r = canvas.getBoundingClientRect()
        return 'канвас ' + canvas.width + 'x' + canvas.height + ', на экране ' + Math.round(r.width) + 'x' + Math.round(r.height) +
            ' в ' + Math.round(r.left) + ',' + Math.round(r.top) + ', окно ' + innerWidth + 'x' + innerHeight + ', dpr ' + devicePixelRatio
    }

    // Asking for a context before the game has made its own would create one, so wait for the loader.
    let gl = null
    function ensureGl() {
        if (gl || loaderState() !== 'none') return
        gl = canvas.getContext('webgl2')
        add('gl', gl ? 'контекст webgl2, preserveDrawingBuffer: ' + (gl.getContextAttributes() || {}).preserveDrawingBuffer
                     : 'webgl2-контекста нет - игра рисует чем-то другим')
    }

    // ---------- reading the screen ----------
    // Always the default framebuffer, whatever the game left bound for its own work.
    function withScreenBound(fn) {
        const readFramebuffer = gl.getParameter(gl.READ_FRAMEBUFFER_BINDING)
        const packBuffer = gl.getParameter(gl.PIXEL_PACK_BUFFER_BINDING)
        if (readFramebuffer) gl.bindFramebuffer(gl.READ_FRAMEBUFFER, null)
        if (packBuffer) gl.bindBuffer(gl.PIXEL_PACK_BUFFER, null)
        try { return fn() } finally {
            if (packBuffer) gl.bindBuffer(gl.PIXEL_PACK_BUFFER, packBuffer)
            if (readFramebuffer) gl.bindFramebuffer(gl.READ_FRAMEBUFFER, readFramebuffer)
        }
    }

    const px = new Uint8Array(4)
    function readPoints(points) {
        return withScreenBound(() => points.map(([fx, fy]) => {
            const x = Math.min(canvas.width - 1, Math.max(0, Math.floor(fx * canvas.width)))
            const y = Math.min(canvas.height - 1, Math.max(0, Math.floor(fy * canvas.height)))
            gl.readPixels(x, canvas.height - 1 - y, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, px)
            return [px[0], px[1], px[2]]
        }))
    }

    // one big read is far cheaper than a hundred small ones: each read is a round trip to the GPU
    function grabFrame() {
        const w = canvas.width, h = canvas.height
        const buf = new Uint8Array(w * h * 4)
        withScreenBound(() => gl.readPixels(0, 0, w, h, gl.RGBA, gl.UNSIGNED_BYTE, buf))
        return {
            at(fx, fy) {
                const x = Math.min(w - 1, Math.max(0, Math.floor(fx * w)))
                const y = Math.min(h - 1, Math.max(0, Math.floor(fy * h)))
                const i = ((h - 1 - y) * w + x) * 4
                return [buf[i], buf[i + 1], buf[i + 2]]
            }
        }
    }

    const isBlack = c => c[0] === 0 && c[1] === 0 && c[2] === 0
    const hex = c => '#' + c.map(v => v.toString(16).padStart(2, '0')).join('')

    // ---------- game frames ----------
    // The first draw call of a frame queues a microtask; it runs once the game has finished that
    // frame and before the browser presents it - the one moment the drawing buffer holds a picture.
    const stats = { browserFrames: 0, gameFrames: 0, draws: 0, blackChecks: 0, black: 0 }
    const endOfFrameJobs = []
    let frameOpen = false, drawsInFrame = 0, gameFrameNo = 0

    function onGameFrameEnd() {
        frameOpen = false
        stats.gameFrames++
        stats.draws += drawsInFrame
        drawsInFrame = 0
        gameFrameNo++
        if (!gl) return
        if (gameFrameNo % BLACK_CHECK_EVERY === 0) {
            stats.blackChecks++
            if (readPoints(BLACK_CHECK_POINTS).every(isBlack)) stats.black++
        }
        for (const job of endOfFrameJobs.splice(0)) {
            try { job() } catch (e) { add('error', 'задача регистратора: ' + e.message) }
        }
    }

    const glProto = WebGL2RenderingContext.prototype
    for (const name of ['drawElements', 'drawArrays', 'drawElementsInstanced', 'drawArraysInstanced', 'drawRangeElements', 'blitFramebuffer']) {
        const original = glProto[name]
        if (typeof original !== 'function') continue
        glProto[name] = function (...args) {
            const result = original.apply(this, args)
            if (this === gl) {
                drawsInFrame++
                if (!frameOpen) { frameOpen = true; queueMicrotask(onGameFrameEnd) }
            }
            return result
        }
        cleanups.push(() => { glProto[name] = original })
    }

    let stopped = false
    function browserFrame() {
        if (stopped) return
        stats.browserFrames++
        requestAnimationFrame(browserFrame)
    }
    requestAnimationFrame(browserFrame)

    // ---------- wasm heap, caught on its next growth ----------
    let wasmMemory = null
    const originalGrow = WebAssembly.Memory.prototype.grow
    WebAssembly.Memory.prototype.grow = function (pages) {
        wasmMemory = this
        return originalGrow.call(this, pages)
    }
    cleanups.push(() => { WebAssembly.Memory.prototype.grow = originalGrow })

    function memoryText() {
        const parts = []
        try { if (wasmMemory) parts.push('wasm ' + Math.round(wasmMemory.buffer.byteLength / 1048576) + ' МБ') } catch (e) {}
        if (performance.memory) parts.push('JS ' + Math.round(performance.memory.usedJSHeapSize / 1048576) + ' МБ')
        return parts.join(', ')
    }

    // ---------- screens ----------
    const gameFpsSamples = []
    const screensSeen = {}
    let lastScreenKey = null, lastGrid = null, screenBusy = false
    let currentScreen = '...'

    function evaluateScreens() {
        if (!gl) return
        const frame = grabFrame()
        const results = Object.entries(SCREENS).map(([name, points]) => {
            let ok = 0
            for (const p of points) {
                const c = frame.at(p.x, p.y)
                const t = p.threshold ?? DEFAULT_THRESHOLD
                if (p.color.every((v, k) => Math.abs(v - c[k]) <= t)) ok++
            }
            return { name, ok, n: points.length }
        })

        const full = results.filter(r => r.ok === r.n)
        let text, key
        if (full.length) {
            text = 'опознан: ' + full.map(r => r.name + ' (' + r.ok + '/' + r.n + ')').join(', ')
            key = full.map(r => r.name).join(',')
            currentScreen = full.map(r => r.name).join(', ')
        } else {
            const near = results.filter(r => r.ok > 0).sort((a, b) => b.ok / b.n - a.ok / a.n).slice(0, 3)
            text = 'не опознан' + (near.length ? '; ближе всего ' + near.map(r => r.name + ' ' + r.ok + '/' + r.n).join(', ') : '')
            key = 'none'
            currentScreen = 'не опознан'
        }

        if (key !== lastScreenKey) {
            lastScreenKey = key
            add('screen', text)
            for (const r of full) screensSeen[r.name] = (screensSeen[r.name] || 0) + 1
        }

        // unknown screens get a colour grid, so a popup or a new screen can be told apart later
        if (!full.length) {
            const grid = []
            for (let row = 0; row < GRID_ROWS; row++) {
                for (let col = 0; col < GRID_COLS; col++) {
                    grid.push(frame.at((col + 0.5) / GRID_COLS, (row + 0.5) / GRID_ROWS))
                }
            }
            const changed = !lastGrid || grid.reduce((sum, c, i) => sum + Math.abs(c[0] - lastGrid[i][0]) + Math.abs(c[1] - lastGrid[i][1]) + Math.abs(c[2] - lastGrid[i][2]), 0) / grid.length > 40
            if (changed) {
                lastGrid = grid
                add('grid', 'сетка ' + GRID_COLS + 'x' + GRID_ROWS + ' (строки сверху вниз): ' + grid.map(hex).join(' '))
            }
        } else {
            lastGrid = null
        }
    }

    const screenTimer = setInterval(() => {
        ensureGl()
        if (!gl || screenBusy || document.hidden) return
        screenBusy = true
        endOfFrameJobs.push(() => { screenBusy = false; evaluateScreens() })
    }, SCREEN_EVERY_MS)
    cleanups.push(() => clearInterval(screenTimer))

    // ---------- periodic stats ----------
    const statsTimer = setInterval(() => {
        const sec = STATS_EVERY_MS / 1000
        const browserFps = Math.round(stats.browserFrames / sec)
        const gameFps = Math.round(stats.gameFrames / sec)
        gameFpsSamples.push(gameFps)
        add('stats', 'браузер ' + browserFps + ' к/с, игра рисует ' + gameFps + ' к/с' +
            (stats.browserFrames ? ' (' + Math.round(stats.gameFrames / stats.browserFrames * 100) + '% кадров)' : '') +
            ', отрисовок на кадр ' + (stats.gameFrames ? Math.round(stats.draws / stats.gameFrames) : 0) +
            ', чёрных чтений после кадра игры ' + stats.black + '/' + stats.blackChecks +
            (document.hidden ? ', вкладка скрыта' : '') + (memoryText() ? ', ' + memoryText() : ''))
        Object.keys(stats).forEach(k => { stats[k] = 0 })
        updatePanel()
    }, STATS_EVERY_MS)
    cleanups.push(() => clearInterval(statsTimer))

    // ---------- clicks: yours are trusted pointer events, the macro dispatches plain mouse events ----------
    function recordClick(e, who) {
        const r = canvas.getBoundingClientRect()
        const fx = (e.clientX - r.left) / r.width
        const fy = (e.clientY - r.top) / r.height
        const point = { x: Number(fx.toFixed(6)), y: Number(fy.toFixed(6)) }
        const queuedAt = performance.now()
        endOfFrameJobs.push(() => {
            const [color] = readPoints([[fx, fy]])
            add('click', who + ' ' + JSON.stringify({ ...point, color }) + ', цвет прочитан через ' + Math.round(performance.now() - queuedAt) + ' мс')
        })
    }
    on(canvas, 'pointerdown', e => { if (e.isTrusted) recordClick(e, 'ты') }, true)
    on(canvas, 'mousedown', e => { if (!e.isTrusted) recordClick(e, 'макрос') }, true)

    // ---------- DOM, visibility, context, errors ----------
    let lastGeometry = geometry()
    function checkGeometry(reason) {
        const g = geometry()
        if (g !== lastGeometry) { lastGeometry = g; add('canvas', reason + ': ' + g) }
    }
    const canvasObserver = new MutationObserver(() => checkGeometry('атрибуты канваса'))
    canvasObserver.observe(canvas, { attributes: true, attributeFilter: ['width', 'height', 'style', 'class'] })
    cleanups.push(() => canvasObserver.disconnect())
    on(window, 'resize', () => checkGeometry('размер окна'))

    if (canvas.parentNode) {
        const parentObserver = new MutationObserver(() => {
            const current = document.getElementById('gameCanvas')
            if (current !== canvas) add('canvas', current ? 'канвас заменён новым элементом' : 'канвас удалён со страницы')
        })
        parentObserver.observe(canvas.parentNode, { childList: true })
        cleanups.push(() => parentObserver.disconnect())
    }

    if (loader) {
        let lastLoader = loaderState()
        const loaderObserver = new MutationObserver(() => {
            const s = loaderState()
            if (s !== lastLoader) { add('loader', lastLoader + ' -> ' + s); lastLoader = s }
        })
        loaderObserver.observe(loader, { attributes: true, attributeFilter: ['style', 'class'] })
        cleanups.push(() => loaderObserver.disconnect())
    }

    on(document, 'visibilitychange', () => add('tab', document.hidden ? 'вкладка скрыта' : 'вкладка снова видна'))
    on(window, 'blur', () => add('tab', 'окно потеряло фокус'))
    on(window, 'focus', () => add('tab', 'окно получило фокус'))
    on(canvas, 'webglcontextlost', () => add('gl', 'КОНТЕКСТ ПОТЕРЯН'))
    on(canvas, 'webglcontextrestored', () => add('gl', 'контекст восстановлен'))
    on(window, 'error', e => { if (e.message) add('error', String(e.message).slice(0, 300)) })
    on(window, 'unhandledrejection', e => add('error', 'promise: ' + String(e.reason).slice(0, 300)))

    // ---------- panel ----------
    const panel = document.createElement('div')
    Object.assign(panel.style, {
        position: 'fixed', left: '8px', bottom: '8px', zIndex: '2147483647', display: 'flex', gap: '6px', alignItems: 'center',
        padding: '4px 8px', background: 'rgba(16,20,24,0.85)', color: '#cfe', font: '12px monospace', border: '1px solid #4f8', borderRadius: '6px'
    })
    const panelText = document.createElement('span')
    panel.appendChild(panelText)
    function button(label, fn) {
        const b = document.createElement('button')
        b.textContent = label
        Object.assign(b.style, { font: '12px sans-serif', padding: '2px 6px', cursor: 'pointer' })
        b.addEventListener('click', e => { e.stopPropagation(); fn() })
        panel.appendChild(b)
    }
    button('Отметка', () => mark(prompt('Что сейчас происходит?') || ''))
    button('Выгрузить', () => dump())
    button('Стоп', () => stop())
    document.body.appendChild(panel)
    cleanups.push(() => panel.remove())

    function updatePanel() {
        const s = Math.round((Date.now() - startedAt) / 1000)
        panelText.textContent = '● REC ' + Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0') +
            ' | игра ' + (gameFpsSamples.length ? gameFpsSamples[gameFpsSamples.length - 1] : '?') + ' к/с | ' + currentScreen
    }
    const panelTimer = setInterval(updatePanel, 1000)
    cleanups.push(() => clearInterval(panelTimer))

    // ---------- commands ----------
    function mark(text) {
        if (text) add('mark', text)
    }

    function summary() {
        const sorted = gameFpsSamples.slice().sort((a, b) => a - b)
        const median = sorted.length ? sorted[Math.floor(sorted.length / 2)] : '?'
        return [
            '=== HWA recorder, сводка этого запуска ===',
            'запись: ' + Math.round((Date.now() - startedAt) / 1000) + ' с, строк в журнале: ' + lines.length,
            'игра рисует, к/с: мин ' + (sorted[0] ?? '?') + ', медиана ' + median + ', макс ' + (sorted[sorted.length - 1] ?? '?'),
            'опознанные экраны: ' + (Object.entries(screensSeen).map(([k, v]) => k + ' x' + v).join(', ') || 'нет'),
            geometry(),
            '==========================================='
        ].join('\n')
    }

    function dump() {
        persist()
        const text = summary() + '\n' + lines.join('\n')
        try { copy(text) } catch (e) {}
        const box = document.createElement('textarea')
        box.value = text
        Object.assign(box.style, {
            position: 'fixed', left: '5%', top: '5%', width: '90%', height: '80%', zIndex: '2147483647',
            font: '11px monospace', background: '#101418', color: '#8fe08f', border: '2px solid #4f8'
        })
        const close = document.createElement('button')
        close.textContent = 'Закрыть'
        Object.assign(close.style, { position: 'fixed', right: '6%', top: '86%', zIndex: '2147483647', padding: '8px 20px' })
        close.onclick = () => { box.remove(); close.remove() }
        document.body.appendChild(box)
        document.body.appendChild(close)
        box.focus()
        box.select()
    }

    function stop() {
        if (stopped) return
        stopped = true
        add('stop', 'запись остановлена')
        persist()
        cleanups.splice(0).forEach(fn => { try { fn() } catch (e) {} })
        delete window.hwaRec
        console.log('HWA recorder остановлен. Журнал сохранён, выгрузить: вставь регистратор снова и нажми «Выгрузить»')
    }

    function clear() {
        lines = []
        persist()
        add('start', 'журнал очищен')
    }

    window.hwaRec = { mark, dump, stop, clear }

    if (lines.length) add('start', '----- новый запуск (страница перезагружалась или регистратор вставлен заново) -----')
    add('start', 'запись начата; ' + geometry() + '; загрузчик: ' + loaderState() + '; вкладка ' + (document.hidden ? 'скрыта' : 'видна') +
        '; ' + ((navigator.userAgent.match(/Chrome\/[\d.]+/) || [''])[0]) + '; эталонов экранов: ' + Object.keys(SCREENS).length)
    ensureGl()
    updatePanel()
    console.log('HWA recorder запущен. Панель внизу слева; hwaRec.mark("текст"), hwaRec.dump(), hwaRec.stop(), hwaRec.clear()')
})()
